using System;using System.Linq;using NUnit.Framework;using CashflowChains.Domain;using LocalGame.Data;
public class ProductionExpansionTests {
 [Test] public void Legacy72CityProgressMigratesWithoutLosingAnything(){var p=new Profile{Stars=new int[72],Best=new long[72]};p.Stars[0]=3;p.Best[0]=1120;p.Credits=650;Profile.Validate(p);Assert.AreEqual(104,p.Stars.Length);Assert.AreEqual(3,p.Stars[0]);Assert.AreEqual(1120,p.Best[0]);Assert.AreEqual(650,p.Credits);}
 [Test] public void EveryExpansionReferenceIsLegalConservedAndThreeStar(){var seen=new System.Collections.Generic.HashSet<string>();for(int i=72;i<104;i++){var m=Campaign.Get(i);var run=new CityRun(i,m.Solution.Copy());var r=run.Preview();Assert.True(r.Conserved(),"city "+i);Assert.Greater(r.Credits,0,"city "+i);Assert.AreEqual(3,run.Stars(r.Credits));Assert.AreEqual(r.Credits,r.Events.Sum(e=>e.Credits));foreach(var n in m.Solution.Nodes)seen.Add(n.Kind);}foreach(var piece in Pieces.All.Skip(24))Assert.That(seen,Does.Contain(piece.Id));}
 [Test] public void UnownedExpansionsNeverBlockTheFreeCampaign(){var p=new Profile();Assert.False(p.CanAccess(72));Assert.False(p.CanAccess(84));p.ApplyPurchase("cc.scenario.harbor","test-harbor");Assert.True(p.CanAccess(72));Assert.False(p.CanAccess(84));p.ApplyPurchase("cc.scenario.finance","test-finance");Assert.True(p.CanAccess(84));Assert.That(p.Credits,Is.EqualTo(350));}
 [Test] public void AllDocumentedProductsHaveExactlyOnceFulfillment(){var p=new Profile();foreach(var sku in CommerceCatalog.All){Assert.True(p.ApplyPurchase(sku.Id,"test-"+sku.Id));Assert.False(p.ApplyPurchase(sku.Id,"test-"+sku.Id));}Assert.AreEqual(1760,p.Gems);Assert.AreEqual(5,p.RerollTickets);Assert.AreEqual(850,p.Credits);Assert.AreEqual(6,p.BlueprintCapacity);p.ApplyPurchase("cc.start.01","another-starter-order");Assert.AreEqual(850,p.Credits);Profile.Validate(p);}
 [Test] public void EntitlementReconciliationKeepsUncertainOfflineOwnership(){var p=new Profile();p.ApplyPurchase("cc.skin.neon","test-neon");p.ReconcilePurchases(new string[0],false);Assert.True(p.Entitlements.Contains("cc.skin.neon"));p.ReconcilePurchases(new string[0],true);Assert.False(p.Entitlements.Contains("cc.skin.neon"));Profile.Validate(p);}
 [Test] public void ForgedPremiumBalanceAndUnknownProductsAreRejected(){Assert.Throws<ArgumentException>(()=>new Profile().ApplyPurchase("invalid.sku","test"));var p=new Profile();p.Gems=100;Assert.Throws<ArgumentException>(()=>Profile.Validate(p));}
 [Test] public void SuccessfulLayoutsRecordActualContributorsAndDiscoveries(){var p=new Profile();var m=Campaign.Get(0);new CityRun(0,m.Solution.Copy()).Activate(p,"test-collection");Assert.That(p.Collection,Does.Contain("home"));Assert.That(p.Collection,Does.Contain("cafe"));Assert.That(p.DiscoveredCombos,Does.Contain("Morning rush"));Assert.That(p.Collection,Does.Not.Contain("bank"));}
 [Test] public void UnconnectedDecorationsDoNotCreateFlowCombos(){var b=Campaign.Get(0).Solution.Copy();b.Budget=2000;b.Nodes.Add(new Node(99,"factory",0,0));b.Nodes.Add(new Node(100,"bank",0,1));var r=Resolver.Run(b);Assert.That(Campaign.Combos(b,r),Does.Not.Contain("Factory town"));Assert.That(Campaign.Combos(b,r),Does.Not.Contain("Financial district"));}
 [Test] public void PaidDeliveryRollsBackUntilDurableSaveAndRedeliveryIsIdempotent(){var p=new Profile();Assert.False(LocalGame.PurchaseDelivery.PersistVerified(p,"cc.gems.small","fixture-verified-order",()=>false));Assert.AreEqual(0,p.Gems);Assert.AreEqual(0,p.Purchases.Count);Assert.True(LocalGame.PurchaseDelivery.PersistVerified(p,"cc.gems.small","fixture-verified-order",()=>true));Assert.True(LocalGame.PurchaseDelivery.PersistVerified(p,"cc.gems.small","fixture-verified-order",()=>true));Assert.AreEqual(90,p.Gems);Assert.AreEqual(1,p.Purchases.Count);Profile.Validate(p);}
 [Test] public void OptionalDraftHasFreeRerollThenExplicitPremiumCostAndCannotUndoIt(){var p=new Profile();var r=new CityRun(24);r.BeginDraft();var cell=Enumerable.Range(0,36).First(c=>(r.Board.Blocked&(1UL<<c))==0&&!r.Board.Nodes.Any(n=>n.X==c%6&&n.Y==c/6));Assert.True(r.Place("farm",cell%6,cell/6));string choices=string.Join(",",r.Allowed);Assert.True(r.RerollDraft(p,"free-reroll"));Assert.AreNotEqual(choices,string.Join(",",r.Allowed));Assert.False(r.RerollDraft(p,"free-reroll"));Assert.AreEqual(0,p.Gems);Assert.True(r.Undo());Assert.AreEqual(1,r.Board.DraftRoll);Assert.False(r.RerollDraft(p,"unfunded-reroll"));p.ApplyPurchase("cc.gems.small","fixture-gems");Assert.True(r.RerollDraft(p,"paid-reroll"));Assert.AreEqual(80,p.Gems);Assert.AreEqual(2,r.Board.DraftRoll);Assert.False(r.RerollDraft(p,"paid-reroll"));new CityRun(24,r.Board.Copy());Profile.Validate(p);}
 [Test] public void CollectionRewardIsClaimedOnceAndNeverCreatesStars(){var p=new Profile();for(int i=0;i<6;i++){var m=Campaign.Get(i);new CityRun(i,m.Solution.Copy()).Activate(p,"collection-city-"+i);}var before=p.Credits;int stars=p.TotalStars;Assert.True(CityCollections.Claim(p,"first-street"));Assert.False(CityCollections.Claim(p,"first-street"));Assert.AreEqual(before+200,p.Credits);Assert.AreEqual(stars,p.TotalStars);Profile.Validate(p);}

 [Test] public void PurchasedSlotsDoNotPreventEarningAllEightFreeSlots(){var p=new Profile();p.Award(0,3,1120,"slot-clear");p.ApplyPurchase("cc.blueprint.4","slot-order");for(int i=0;i<7;i++)p.Grant("slot-fixture-"+i,1000);for(int i=0;i<6;i++)Assert.True(p.BuyBlueprintSlot());Assert.AreEqual(8,p.EarnedBlueprintCapacity);Assert.AreEqual(12,p.BlueprintCapacity);Assert.False(p.BuyBlueprintSlot());Profile.Validate(p);}
 [Test] public void LegacyStarterBoardsExpandWithoutChangingLayoutOrScore(){for(int i=3;i<12;i++){if(i==6||i==10)continue;var mission=Campaign.Get(i);var old=mission.Solution.Copy();old.Width=old.Height=4;long score=Resolver.Run(old,mission.Multiplier).Credits;var restored=new CityRun(i,old);Assert.AreEqual(5,restored.Board.Width);Assert.AreEqual(4,old.Width);Assert.AreEqual(score,restored.Preview().Credits);}}
 [Test] public void CorruptPurchaseEntryFailsValidationWithoutNullDereference(){var p=new Profile();p.Purchases.Add(null);Assert.Throws<ArgumentException>(()=>Profile.Validate(p));}

 [Test] public void TenThousandAllBuildingBoardsConserveAndHaveExactMoneyLedger(){var rng=new Random(104033);var kinds=Pieces.All.Select(p=>p.Id).ToArray();for(int sample=0;sample<10000;sample++){var b=new Board{Width=6,Height=6,Budget=100000,ImportQuota=sample%3==0?16:0,ImportCost=sample%4};for(int c=0;c<36;c++)if(rng.Next(4)==0)b.Nodes.Add(new Node(c+1,kinds[rng.Next(kinds.Length)],c%6,c/6,rng.Next(4)){InitialGoods=rng.Next(5),InitialEnergy=rng.Next(3)});var r=Resolver.Run(b);Assert.True(r.Conserved(),"all-building case "+sample);Assert.AreEqual(r.Credits,r.Events.Sum(e=>e.Credits));Assert.AreEqual(r.Trace(),Resolver.Run(b).Trace());for(int k=0;k<3;k++)Assert.AreEqual(r.Initial[k]+r.Generated[k],r.Consumed[k]+r.Spilled[k]+r.Remaining[k]);Assert.LessOrEqual(r.Events.Count,10000);}}

}
